#include "Session.h"
#include "catalog/type_registry.h"
#include "commands/DdlExecutor.h"
#include "commands/TableManage.h"
#include "common/DbError.h"
#include "expression/ExprEvaluator.h"
#include "expression/expr_helper.h"
#include "expression/prepared_query_execution.h"
#include "parser/parser.h"
#include "test_utils.h"
#include <functional>
#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

extern dbms::StorageEngine g_engine;

int main() {
    using namespace dbms;
    TypeRegistry::instance().bootstrap();
    const std::string fixture="factorial_signature", database=testDbPath(fixture);
    cleanupTestDb(fixture); if(g_engine.createDatabase(database)!=DBStatus::OK)return 2;
    Session session; session.username="testuser";session.permission=1;session.currentDB=database;
    auto* previous=currentSession();setCurrentSession(&session);
    struct Restore {Session* previous;~Restore(){setCurrentSession(previous);}} restore{previous};
    size_t controls=0,failures=0;
    const auto require=[](bool value){if(!value)throw std::runtime_error("value mismatch");};
    const auto check=[&](const std::string& label,const std::function<void()>& action) {
        ++controls;try{action();}catch(const std::exception& error){++failures;std::cerr<<"FACTORIAL_SIGNATURE_FAIL "<<label.substr(0,200)<<" : "<<error.what()<<'\n';}
    };
    const auto state=[](const std::exception& error) {
        if(const auto* typed=dynamic_cast<const DbError*>(&error))return typed->sqlState();
        const std::string text=error.what();const auto start=text.find("SQLSTATE ");
        return start==std::string::npos?std::string{}:text.substr(start+9,5);
    };
    struct Case {std::string sql,value,type,state;bool null,zeroRows;};
    const std::vector<Case> cases={
        {"SELECT factorial() AS v","","numeric","42883",true,false},
        {"SELECT factorial(5,6) AS v","","numeric","42883",true,false},
        {"SELECT factorial(5::smallint) AS v","120","numeric","",false,false},
        {"SELECT factorial(5::integer) AS v","120","numeric","",false,false},
        {"SELECT factorial(5::bigint) AS v","120","numeric","",false,false},
        {"SELECT factorial(5::numeric) AS v","","numeric","42883",true,false},
        {"SELECT factorial(5.1::numeric) AS v","","numeric","42883",true,false},
        {"SELECT factorial(5::real) AS v","","numeric","42883",true,false},
        {"SELECT factorial(5::double precision) AS v","","numeric","42883",true,false},
        {"SELECT factorial('5') AS v","120","numeric","",false,false},
        {"SELECT factorial('5'::text) AS v","","numeric","42883",true,false},
        {"SELECT factorial(true) AS v","","numeric","42883",true,false},
        {"SELECT factorial('2000-01-01'::date) AS v","","numeric","42883",true,false},
        {"SELECT factorial(ARRAY[5]) AS v","","numeric","42883",true,false},
        {"SELECT factorial(NULL) AS v","","numeric","",true,false},
        {"SELECT factorial(NULL::bigint) AS v","","numeric","",true,false},
        {"SELECT factorial(NULL::numeric) AS v","","numeric","42883",true,false},
        {"SELECT factorial(NULL::text) AS v","","numeric","42883",true,false},
        {"SELECT factorial('bad') AS v","","numeric","22P02",true,false},
        {"SELECT factorial('5.0') AS v","","numeric","22P02",true,false},
        {"SELECT factorial('NaN') AS v","","numeric","22P02",true,false},
        {"SELECT factorial('Infinity') AS v","","numeric","22P02",true,false},
        {"SELECT factorial(-1) AS v","","numeric","22003",true,false},
        {"SELECT factorial(0) AS v","1","numeric","",false,false},
        {"SELECT factorial(1) AS v","1","numeric","",false,false},
        {"SELECT factorial(20) AS v","2432902008176640000","numeric","",false,false},
        {"SELECT factorial(100) AS v","93326215443944152681699238856266700490715968264381621468592963895217599993229915608941463976156518286253697920827223758251185210916864000000000000000000000000","numeric","",false,false},
        {"SELECT factorial(1661) AS v","","numeric","",false,false},
        {"SELECT factorial(1662) AS v","","numeric","",false,false},
        {"SELECT factorial(32178) AS v","","numeric","22003",true,false},
        {"SELECT factorial('-9223372036854775808'::bigint) AS v","","numeric","22003",true,false},
        {"SELECT factorial('9223372036854775807'::bigint) AS v","","numeric","22003",true,false},
        {"SELECT factorial(x=>5) AS v","","numeric","42883",true,false},
        {"SELECT factorial(num=>5) AS v","","numeric","42883",true,false},
        {"SELECT factorial() AS v WHERE false","","numeric","42883",true,true},
        {"SELECT factorial() AS v LIMIT 0","","numeric","42883",true,true},
        {"SELECT factorial(1,2) AS v WHERE false","","numeric","42883",true,true},
        {"SELECT factorial(1,2) AS v LIMIT 0","","numeric","42883",true,true},
        {"SELECT factorial('bad') AS v WHERE false","","numeric","22P02",true,true},
        {"SELECT factorial('bad') AS v LIMIT 0","","numeric","22P02",true,true},
        {"SELECT factorial(1::text) AS v WHERE false","","numeric","42883",true,true},
        {"SELECT factorial(1::text) AS v LIMIT 0","","numeric","42883",true,true},
        {"SELECT factorial(-1) AS v WHERE false","","numeric","22003",true,true},
        {"SELECT factorial(-1) AS v LIMIT 0","","numeric","22003",true,true},
        {"SELECT factorial(NULL::text) AS v WHERE false","","numeric","42883",true,true},
        {"SELECT factorial(NULL::text) AS v LIMIT 0","","numeric","42883",true,true},
        {"SELECT factorial(5) OVER () AS v","","numeric","42809",true,false},
        {"SELECT factorial(DISTINCT 5) AS v","","numeric","42809",true,false},
        {"SELECT factorial(5) FILTER (WHERE true) AS v","","numeric","42809",true,false},
        {"SELECT factorial(5 ORDER BY 1) AS v","","numeric","42809",true,false},
        {"SELECT factorial('bad') OVER () AS v","","numeric","42809",true,false},
        {"SELECT factorial(DISTINCT 'bad') AS v","","numeric","42809",true,false},
        {"SELECT factorial('bad') FILTER (WHERE true) AS v","","numeric","42809",true,false},
        {"SELECT factorial('bad' ORDER BY 1) AS v","","numeric","42809",true,false},
        {"SELECT factorial(1::text) OVER () AS v","","numeric","42883",true,false},
        {"SELECT factorial(DISTINCT 1::text) AS v","","numeric","42883",true,false},
        {"SELECT factorial(1::text) FILTER (WHERE true) AS v","","numeric","42883",true,false},
        {"SELECT factorial(1::text ORDER BY 1) AS v","","numeric","42883",true,false},
        {"SELECT factorial(1) FILTER (WHERE missing) AS v","","numeric","42703",true,false},
        {"SELECT factorial(1) FILTER (WHERE 1) AS v","","numeric","42804",true,false},
        {"SELECT factorial(1) FILTER (WHERE NULL) AS v","","numeric","42809",true,false},
        {"SELECT COALESCE(1::numeric,factorial(-1)) AS v","1","numeric","",false,false},
        {"SELECT CASE WHEN false THEN factorial(-1) ELSE 1::numeric END AS v","1","numeric","",false,false},
        {"SELECT COALESCE(1::numeric,factorial('bad')) AS v","","numeric","22P02",true,false},
        {"SELECT CASE WHEN false THEN factorial('bad') ELSE 1::numeric END AS v","","numeric","22P02",true,false},
        {"SELECT \"FACTORIAL\"(5) AS v","","numeric","42883",true,false},
        {"SELECT pg_catalog.factorial(5) AS v","120","numeric","",false,false},
        {"SELECT factorial(5)+factorial(4) AS v","144","numeric","",false,false},
        {"SELECT 42 AS v","42","integer","",false,false},
        {"SELECT factorial(448) AS v","","numeric","",false,false},
        {"SELECT factorial(449) AS v","","numeric","",false,false},
        {"SELECT factorial(450) AS v","","numeric","",false,false},
        {"SELECT factorial(451) AS v","","numeric","",false,false},
    };
    for(const auto& test:cases)check(test.sql,[&] {
        std::shared_ptr<PreparedQuery> query;std::string actual;
        try{query=std::make_shared<PreparedQuery>(g_engine.prepareBoundQuery(database,test.sql));}
        catch(const std::exception& error){actual=state(error);}
        if(!test.state.empty()&&test.state!="22003"){require(actual==test.state);return;}
        // Analysis and construction are pure even for negative constants.
        require(actual.empty()&&query&&query->output.size()==1&&query->output[0].type==test.type);
        auto* select=dynamic_cast<SelectStmt*>(query->ast.get());require(select&&select->selectList.size()==1);
        PreparedQueryExecution execution(query,&g_engine,database);
        auto* node=select->selectList.front().expr.get();execution.prepareExpression(node);
        try{execution.planStatementConstants(query->ast.get());}catch(const std::exception& error){actual=state(error);}
        require(actual==test.state);
        if(actual.empty()&&!test.zeroRows) {
            const auto value=execution.evaluate(node,execution.context());
            require(value.typeName==test.type&&value.isNull==test.null&&(test.null||value.value==test.value));
        }
        execution.closeChildCursors();
    });
    for(const std::string type:{"smallint","integer","bigint","int2","int4","int8","numeric","decimal","real","double precision","text","boolean"})
        for(const bool null:{false,true})check("native typed row "+type+std::to_string(null),[&] {
            SQLParser parser;auto parsed=parser.parseForBinding("SELECT factorial(a) AS v");
            auto* select=parsed.success?dynamic_cast<SelectStmt*>(parsed.stmt.get()):nullptr;require(select);
            ExprEvaluator evaluator;evaluator.setCurrentDB(database);auto* node=select->selectList.front().expr.get();evaluator.bindScalarFunctions(node,&g_engine);
            RowContext row;row.set("a",ExprValue(type,type=="boolean"?"t":"5",null));
            const bool valid=type=="smallint"||type=="integer"||type=="bigint"||type=="int2"||type=="int4"||type=="int8";
            try{const auto value=evaluator.eval(node,row);require(valid&&value.typeName=="numeric"&&value.isNull==null&&(null||value.value=="120"));}
            catch(const std::exception& error){require(!valid&&state(error)=="42883");}
        });
    for(const std::string context:{database,std::string{}})for(const char volatility:{'i','v'})for(const std::string args:{"'raw'","1,2"})
        check("opaque replacement "+context+volatility+args,[&] {
            ExprEvaluator evaluator;evaluator.setCurrentDB(context);size_t calls=0;
            evaluator.registerFunction("factorial",[&](const std::vector<ExprValue>& values){++calls;require(values.size()==(args=="'raw'"?1:2));return ExprValue("text","opaque actual callback");},volatility);
            SQLParser parser;auto parsed=parser.parseForBinding("SELECT factorial("+args+") AS v");
            auto* select=parsed.success?dynamic_cast<SelectStmt*>(parsed.stmt.get()):nullptr;require(select);
            auto* call=dynamic_cast<FunctionCallExpr*>(select->selectList.front().expr.get());require(call);
            require(evaluator.scalarFunctionResultType(call,&g_engine).empty()&&evaluator.scalarFunctionIdentity(call,&g_engine).rfind("native",0)==0);
            require(ExprHelper::inferParsedInputType(call,{},context,&g_engine,&evaluator)=="unknown"&&calls==0);
            evaluator.bindScalarFunctions(call,&g_engine);require(calls==0);
            const auto value=evaluator.eval(call,RowContext{});
            require(calls==1&&value.typeName=="text"&&!value.isNull&&value.value=="opaque actual callback"&&evaluator.volatility("factorial")==volatility);
        });
    for(const bool unused:{false,true})check("argument demand "+std::to_string(unused),[&] {
        ExprEvaluator evaluator;evaluator.setCurrentDB(database);size_t calls=0;
        evaluator.registerFunction("factorial_effect",[&](const std::vector<ExprValue>&){++calls;return ExprValue("bigint","5");});
        const std::string expression="factorial(factorial_effect()::bigint)";
        SQLParser parser;auto parsed=parser.parseForBinding("SELECT "+(unused?"COALESCE(7::numeric,"+expression+")":expression)+" AS v");
        auto* select=parsed.success?dynamic_cast<SelectStmt*>(parsed.stmt.get()):nullptr;require(select);
        auto* node=select->selectList.front().expr.get();evaluator.bindScalarFunctions(node,&g_engine);require(calls==0);
        const auto value=evaluator.eval(node,RowContext{});
        require(calls==(unused?0:1)&&value.typeName=="numeric"&&!value.isNull&&value.value==(unused?"7":"120"));
    });
    check("actual immutable declaration",[&]{ExprEvaluator evaluator;require(evaluator.volatility("factorial")=='i');});
    DdlExecutor ddl;
    if(ddl.executeSql("CREATE SCHEMA factorial_owner",session)||ddl.executeSql("CREATE FUNCTION factorial_owner.factorial(text) RETURNS text LANGUAGE SQL AS 'SELECT $1'",session)||
       ddl.executeSql("CREATE TABLE factorial_danger(a bigint)",session)||ddl.executeSql("INSERT INTO factorial_danger VALUES(-1)",session))return 2;
    for(const std::string expression:{"factorial_owner.factorial('stored actual owner'::text)","pg_catalog.factorial('5'::text)"})
        check(expression,[&] {
            std::string actual;std::shared_ptr<PreparedQuery> query;
            try{query=std::make_shared<PreparedQuery>(g_engine.prepareBoundQuery(database,"SELECT "+expression+" AS v"));}catch(const std::exception& error){actual=state(error);}
            if(expression.front()=='p'){require(actual=="42883");return;}
            require(actual.empty()&&query&&query->output.size()==1&&query->output[0].type=="text");
            auto* select=dynamic_cast<SelectStmt*>(query->ast.get());require(select);
            PreparedQueryExecution execution(query,&g_engine,database);execution.prepareExpression(select->selectList.front().expr.get());execution.planStatementConstants(query->ast.get());
            const auto value=execution.evaluate(select->selectList.front().expr.get(),execution.context());
            require(value.typeName=="text"&&!value.isNull&&value.value=="stored actual owner");execution.closeChildCursors();
        });
    check("planning does not consume sequence",[&] {
        require(!ddl.executeSql("CREATE SEQUENCE factorial_effects",session));
        auto query=std::make_shared<PreparedQuery>(g_engine.prepareBoundQuery(database,"SELECT factorial(nextval('factorial_effects')) AS v"));
        auto* select=dynamic_cast<SelectStmt*>(query->ast.get());require(select);
        PreparedQueryExecution execution(query,&g_engine,database);execution.prepareExpression(select->selectList.front().expr.get());execution.planStatementConstants(query->ast.get());
        require(g_engine.nextval(database,"factorial_effects")==1);
        const auto value=execution.evaluate(select->selectList.front().expr.get(),execution.context());
        require(value.typeName=="numeric"&&!value.isNull&&value.value=="2");
        require(g_engine.nextval(database,"factorial_effects")==3);execution.closeChildCursors();
    });
    for(const std::string tail:{""," WHERE false"," LIMIT 0"})check("variable planning "+tail,[&] {
        auto query=std::make_shared<PreparedQuery>(g_engine.prepareBoundQuery(database,"SELECT factorial(a) AS v FROM factorial_danger"+tail));
        require(query->output.size()==1&&query->output[0].type=="numeric");
        PreparedQueryExecution execution(query,&g_engine,database);execution.planStatementConstants(query->ast.get());execution.closeChildCursors();
    });
    require(controls==114);require(g_engine.dropDatabase(database)==DBStatus::OK);cleanupTestDb(fixture);finalCleanupTestData();
    std::cout<<"FACTORIAL_SIGNATURE_COMPLETE "<<controls<<" FAILURES "<<failures<<std::endl;
    return failures?1:0;
}
